def is_primitive_root(a, p):
    a_mod = a % p
    if a_mod == 0: return False
    factors = prime_factors(p - 1)
    for q in factors:
        if pow(a_mod, (p - 1) // q, p) == 1:
            return False
    return True

def primitive_root_index(a, p):
    ord_a = multiplicative_order(a % p, p)
    return (p - 1) // ord_a

def artin_constant_approx(num_primes=100):
    product = 1.0
    count, n = 0, 2
    while count < num_primes:
        if is_prime(n):
            product *= (1 - 1.0 / (n * (n - 1)))
            count += 1
        n += 1
    return product
